#!/usr/bin/env python3
"""Scan all paragraphs; report which look like all-caps headlines."""
import re
from pathlib import Path

doc = Path("quarterly_report_unpacked/word/document.xml").read_text(encoding="utf-8")
paras = re.findall(r"<w:p\b.*?</w:p>", doc, flags=re.S)

def text_of(p):
    return "".join(re.findall(r"<w:t[^>]*>(.*?)</w:t>", p, flags=re.S))

for i, p in enumerate(paras):
    t = text_of(p)
    has_letter = re.search(r"[A-Za-z]", t)
    all_caps = has_letter and t == t.upper()
    short = len(t) <= 40
    if all_caps or short:
        print(f"[{i}] allcaps={bool(all_caps)} short={short} len={len(t)} text={t!r}")

